<template>
  <div class="container" v-loading="loading">
    <div class="vote_add_top" @click="return_vote_list_add">
      <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回列表
    </div>
    <div class="container-box">
      <div class="editbox" @click="all_click">
        <!-- 标题 -->
        <div class="title">
          <input type="text"   v-model="vote_data.vote_title" :placeholder="vote_title_placeholder" class="title_box" @focus="focus_title" @blur="blur_title"/>
        </div>

        <!-- 副标题添加图片 -->
        <div class="s-title" :class="title_desc_class" ref="desc_title">
          <div class="s-title-text title_vote_des_div" @mouseover="hover_info" @mouseleave="leave_info">
            <el-input
              class="title_vote_des" :class="{'gray_line': dec_gray_line, 'choose_line': dec_choose_line, 'style_center': vote_des_style_class=='style_center', 'style_left': vote_des_style_class=='style_left'}"
              type="textarea"
              :autosize="{ minRows: 1, maxRows: 10}"
              placeholder="点击设置描述"
              @focus="focus_info"
              maxlength="1000"
              v-model="vote_data.vote_des">
            </el-input>
          </div>
          <div class="cell" v-show="showcell"></div>
          <div class="editalign" v-show="showe_title_desc">
            <div class="align-box">
              <div class="align-l" :class="left_class" @click="change_style('left')"></div>
              <div class="align-r" :class="center_class" @click="change_style('center')"></div>
            </div>
            <div class="align-icon" @click="up_img">
              <el-row class="up-img-box">
                <el-col :span="2"><div class="align-up-img"></div></el-col>
                <el-col :span="22" class="img_tip">&nbsp;添加图片(建议尺寸640*278)</el-col>
              </el-row>
            </div>
          </div>
        </div>
        <div class="s-title_img" ref="desc_title_img">
          <el-row>
            <input accept="image/*" type="file" name="file" ref="tempUploadFile" v-on:change="uploadPic" style="display: none;"/>
              <div class="block" v-for="(item, index) in vote_data.vote_image" :key="index">
                <el-col :span="22">
                  <el-image
                    style="width: 100%; height: 200px"
                    :src="item.file_url"
                    fit="cover">
                  </el-image>
                </el-col>
                <el-col :span="2" class="tip_info">
                  <div @click="del_img(index)">
                    <i class="el-icon-close"></i>
                  </div>
                </el-col>
              </div>
          </el-row>
        </div>


        <div v-for="(item, index) in vote_block" :key='index'>
          <completion_vote ref="components_tip_box" :vote-order="index+1" :vote_block="item" :block_length="vote_block.length" v-if="item.block_type==1 || item.block_type==2"></completion_vote>
          <choice_vote ref="components_tip_box" :vote-order="index+1" :vote_block="item" :block_length="vote_block.length" v-if="item.block_type==3 || item.block_type==4"></choice_vote>
          <score_vote ref="components_tip_box" :vote-order="index+1" :vote_block="item" :block_length="vote_block.length" v-if="item.block_type==5"></score_vote>
        </div>
      </div>
      <div class="add">
        <div class="addbox">
          <div class="addtext">添加题目</div>
          <div class="addbtn">
            <el-row>
              <el-button size="small" @click="add_tip(1)">填空题</el-button>
              <el-button size="small" @click="add_tip(2)">选择题</el-button>
              <el-button size="small" @click="add_tip(3)">评分题</el-button>
            </el-row>
          </div>
        </div>
        <el-row type="flex" class="row-bg" justify="space-between" style="margin:20px 15px">
          <el-col :span="6">
            <div class="grid-content bg-purple">设置</div>
          </el-col>
          <el-col :span="6">
            <div
              class="grid-content bg-purple-light"
              style="text-align:right"
              @click="dialogFormVisible = true">
              <i class="el-icon-setting" style="font-size: 20px;"></i>
            </div>
          </el-col>
        </el-row>
        <div v-if="limit_creator_set!=2">
          <el-button type="primary" style="width:270px;margin-top:5px" @click="finish_vote">完成创建</el-button>
        </div>
      </div>
    </div>
    <!-- 弹出层 -->
    <el-dialog title="设置" :visible.sync="dialogFormVisible" width="450px">
      <el-form :model="vote_data" style="text-align:left">

        <el-form-item label="投票日期">
          <div class="block" style="float:left">
            <el-date-picker
              class="block_date"
              v-model="vote_data.date"
              type="datetimerange"
              :picker-options="pickerOptions"
              size="mini"
              value-format="yyyy-MM-dd HH:mm"
              format="yyyy-MM-dd HH:mm"
              range-separator="至"
              start-placeholder="开始日期"
              end-placeholder="结束日期">
            </el-date-picker>
          </div>
        </el-form-item>
        <el-form-item label="是否只允许12312312业主参与（家属不可投票）" v-if="from=='house'">
          <el-switch v-model="vote_data.limit_type" style="float:right;margin-top:10px" active-value="1" inactive-value="0"></el-switch>
        </el-form-item>
        <el-form-item label="每户是否只允许投票一次" v-if="from=='house'">
          <el-switch v-model="vote_data.house_limit_once" style="float:right;margin-top:10px" active-value="1" inactive-value="0"></el-switch>
        </el-form-item>
        <el-form-item label="每人可投票次数（默认每人一票）">
          <el-input class="vote_sort_input" style="float: right;"
                    type="text"
                    placeholder="请输入投票次数"
                    v-model="vote_data.limit_num"
                    maxlength="15"
                    size="mini"
                    :blur="change_limit_num()">
          </el-input>
        </el-form-item>
        <el-form-item label="是否允许填写者再次修改" v-if="set_show">
          <el-switch v-model="vote_data.limit_user_set" style="float:right;margin-top:10px" active-value="1" inactive-value="2"></el-switch>
        </el-form-item>
        <el-form-item label="是否公开投票结果">
          <el-switch v-model="vote_data.limit_open" style="float:right;margin-top:10px" active-value="1" inactive-value="2"></el-switch>
        </el-form-item>
        <el-form-item label="投票活动状态">
          <el-switch v-model="vote_data.status" style="float:right;margin-top:10px" active-value="1" inactive-value="0"></el-switch>
        </el-form-item>
        <el-form-item label="投票编辑保存后是否可修改">
          <el-switch v-model="vote_data.limit_creator_set" style="float:right;margin-top:10px" active-value="1" inactive-value="2"></el-switch>
        </el-form-item>
        <el-form-item label="投票活动排序值">
          <el-input class="vote_sort_input"
            type="text"
            placeholder="请输入排序值"
            v-model="vote_data.vote_sort"
            maxlength="11"
            size="mini">
          </el-input>
          排序值越高展示越靠前
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible = false">取 消</el-button>
        <el-button type="primary" @click="dialogFormVisible = false">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
  import completion_vote from '../components/completion_vote'
  import choice_vote from '../components/choice_vote'
  import score_vote from '../components/score_vote'
  export default {
    name: 'add_vote',
    components: {
      completion_vote,choice_vote,score_vote
    },
    data() {
      return {
        pickerOptions: {
          shortcuts: [{
            text: '一周',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              end.setTime(end.getTime() + 3600 * 1000 * 24 * 7);
              picker.$emit('pick', [start, end]);
            }
          }, {
            text: '一个月',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              end.setTime(end.getTime() + 3600 * 1000 * 24 * 30);
              picker.$emit('pick', [start, end]);
            }
          }, {
            text: '三个月',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              end.setTime(end.getTime() + 3600 * 1000 * 24 * 90);
              picker.$emit('pick', [start, end]);
            }
          }, {
            text: '六个月',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              end.setTime(end.getTime() + 3600 * 1000 * 24 * 120);
              picker.$emit('pick', [start, end]);
            }
          }, {
            text: '一年',
            onClick(picker) {
              const end = new Date();
              const start = new Date();
              end.setTime(end.getTime() + 3600 * 1000 * 24 * 365);
              picker.$emit('pick', [start, end]);
            }
          }]
        },
        loading: false,
        vote_id: '',
        vote_block: [
          {
            'block_title': '',
            'block_type': '1',
            'is_write': '2',
            'block_type_options': [{
              value: '1',
              label: '单行'
            }, {
              value: '2',
              label: '多行'
            }]
          }
        ],
        vote_data:{
          'vote_title': '',
          'vote_des_style': '',
          'date': '',
          'limit_type': '0',
          'house_limit_once': '0',
          'limit_user_set': '1',
          'limit_open': '1',
          'limit_creator_set': '1',
          'status': '1',
          'vote_sort': '',
          'vote_image': []
        },
        vote_title_placeholder: '请输入表单标题',
        title_desc_class:'',
        dec_gray_line: false,
        dec_choose_line: false,
        is_click: false,
        now_node:'desc_title',
        showeditAlign: false,
        left_class: '',
        center_class: 'active',
        showcell: false,
        dialogFormVisible: false,
        formLabelWidth: "120px",
        showe_title_desc: false,
        voteOrder: 0,
        vote_des_style_class: 'style_center',
        from: 'house',
        set_show: true,
        limit_creator_set: 1
      }
    },
    created () {
      this.vote_id = this.$route.query.vote_id;
      var from = this.$route.query.from;
      if (from) {
        this.from = from;
      }
      if (this.vote_id>0) {
        let param = {};
        param['vote_id'] = this.vote_id;
        this.voteDetail(param);
      }
    },
    methods: {
      change_limit_num: function () {
        var limit_num = this.vote_data.limit_num;
        console.log('limit_num', limit_num);
        if (limit_num && limit_num>1) {
          this.set_show = false;
        } else {
          this.set_show = true;
        }
      },
      return_vote_list_add: function () {
        this.$router.replace({ path: '/vote_list', query: { from: this.from }});
      },
      uploadPic(e) {
          console.log('e', e);
        this.loading = true;
        let _self = this;
        let inputFile = e.target;
        if (!inputFile.files || inputFile.files.length <= 0) {
          return;
        }
        let file_msg = inputFile.files[0];
          console.log('file_msg', file_msg)
        let formData = new FormData()
        formData.append('file', file_msg)
        this.ajaxUploadPic(formData)
      },
      // 上传图片
      async ajaxUploadPic(param) {
        var url_params = '&from=house';
        if (this.from) {
          url_params = '&from=' + this.from;
        }
        let res = await this.$api.ajaxUploadPic(param, url_params);
        if (res) {
          console.log(`res: `, res);
          if (!this.vote_data.vote_image) {
            this.vote_data.vote_image = [];
          }
          this.vote_data.vote_image.push(res);
        }
        this.loading = false;
      },
      del_img(index) {
        // 删一个数组元素
        console.log('删一个数组元素',index);
        if (this.vote_data.vote_image[index]) {
          this.vote_data.vote_image.splice(index,1);
        }
      },
      // 获取投票详情
      async voteDetail(param) {
        var url_params = '&from=house';
        if (this.from) {
          url_params = '&from=' + this.from;
        }
        let res = await this.$api.voteDetail(param, url_params);
        if (res) {
          console.log(`res: `, res);
          this.vote_data = res;
          this.$set(this.vote_data, 'house_limit_once', this.vote_data.house_limit_once ? String(this.vote_data.house_limit_once) : '0');
          if (res && res.vote_des_style) {
            if ('text-align:left;' == res.vote_des_style) {
                this.vote_data.vote_des_style = 'text-align:left;';
                this.vote_des_style_class = 'style_left';
                this.left_class = 'active';
                this.center_class = '';
            } else {
                this.vote_data.vote_des_style = 'text-align:center;';
                this.vote_des_style_class = 'style_center';
                this.left_class = '';
                this.center_class = 'active';
            }
          }
          this.vote_block = res.vote_block;
          var limit_num = res.limit_num;
          if (limit_num && limit_num>1) {
            this.set_show = false;
          } else {
            this.set_show = true;
          }
          this.limit_creator_set = res.limit_creator_set;
        }
      },
      // 编辑投票
      async editVote(param) {
        var url_params = '&from=house';
        let _this=this;
        if (_this.from) {
          url_params = '&from=' + _this.from;
        }
        let res = await this.$api.editVote(param, url_params);
        if (res) {
          this.$message({
            type: 'success',
            message: '修改成功!'
          });
          _this.$router.replace({ path: '/vote_list', query: { from: this.from }});
        } else if (res.errorMsg) {
          this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      // 添加投票
      async addVote(param) {
        var url_params = '&from=house';
        let _this=this;
        if (_this.from) {
          url_params = '&from=' + _this.from;
        }
        let res = await this.$api.addVote(param, url_params);
        if (res) {
          this.$message({
            type: 'success',
            message: '添加成功!'
          });
        } else if (res.errorMsg) {
          this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        _this.$router.replace({ path: '/vote_list', query: { from: this.from }});
        return res;
      },
      finish_vote: function(e) {
        console.log('vote_block结果：',this.vote_block);
        console.log('vote_data结果：',this.vote_data);
        if (!this.vote_data.vote_title) {
          this.$message({
            message: '请输入投票标题',
            type: 'warning'
          });
          return false;
        }
        if (!this.vote_block) {
          this.$message({
            message: '最少创建一个问题',
            type: 'warning'
          });
          return false;
        }
        let vote_block = this.vote_block;
        for (let m in vote_block) {
          if (vote_block[m] && !vote_block[m]['block_title']) {
            this.$message({
              message: '问题不能为空',
              type: 'warning'
            });
            return false;
          }
        }
        if (!this.vote_data.date) {
          this.$message({
            message: '请选择投票时间',
            type: 'warning'
          });
          return false;
        }
        let start_time = this.vote_data.date[0];
        let end_time = this.vote_data.date[1];
        this.vote_data.start_time = start_time;
        this.vote_data.end_time = end_time;

        let param = this.vote_data;
        param['vote_block'] = this.vote_block;
        console.log('param：',param);
        if (this.vote_id && this.vote_id>0) {
          param['vote_id'] = this.vote_id;
          this.editVote(param);
        } else {
          this.addVote(param);
        }
      },
      tip_info: function(index) {
        // 避免关联导致数据同步，从新赋值
        if (1==index) {
          let  completion_vote_msg = {
            'block_title': '',
            'block_type': '1',
            'is_write': '2'
          };
          return completion_vote_msg;
        } else if (2==index) {
          let choice_vote_msg = {
            'block_title': '',
            'block_type': '3',
            'is_write': '2',
            'is_other_options': false,
            'info_options': [{
              value: '0',
              label: '选项',
              option_name: '',
              option_type: '0',
            }, {
              value: '1',
              label: '选项',
              option_name: '',
              option_type: '0',
            }]
          };
          return choice_vote_msg;
        } else if (3==index) {
          let score_vote_msg = {
            'block_title': '',
            'block_type': '5',
            'is_write': '2',
          }
          return score_vote_msg;
        }
      },
      add_tip(index) {
        let msg = this.tip_info(index);
        this.vote_block.push(msg);
      },
      data_set(index, data) {
        let key = index - 1;
        console.log('data_set',key);
        this.$set(this.vote_block, key, data)
      },
      copy_tip(index,vote_block_msg,type) {
        let key = index;
        let block_msg = '';
        let vote_block = this.vote_block;
        console.log('data_set',key);
        let msg = '';
        if (type>0) {
          block_msg = this.tip_info(type);
          block_msg = this.copy_data(vote_block_msg, block_msg, type)
        } else {
          block_msg = vote_block_msg;
        }
        this.vote_block.splice(key,0,block_msg);
      },
      copy_data(data,copy_data, type) {
        // 避免关联导致数据同步，从新赋值
        if (1==type) {
          copy_data.block_title = data.block_title;
          copy_data.block_type = data.block_type;
          copy_data.is_write = data.is_write;
        } else if(2==type) {
          copy_data.block_title = data.block_title;
          copy_data.block_type = data.block_type;
          copy_data.is_write = data.is_write;
          copy_data.is_other_options = data.is_other_options;
          copy_data.info_options = [];
          for (let n in data.info_options) {
            if (data.info_options[n]) {
              copy_data.info_options[n] = {};
              copy_data.info_options[n]['value'] = data.info_options[n]['value'];
              copy_data.info_options[n]['label'] = data.info_options[n]['label'];
              copy_data.info_options[n]['option_name'] = data.info_options[n]['option_name'];
              copy_data.info_options[n]['option_type'] = data.info_options[n]['option_type'];
            }
          }
        } else if(3==type) {
          copy_data.block_title = data.block_title;
          copy_data.block_type = data.block_type;
          copy_data.is_write = data.is_write;
        }
        return copy_data;
      },
      move_tip(index, msg) {
        let key = index - 1;
        let block_msg = this.vote_block[key];
        if (msg && 'up'==msg) {
          let up_key = key - 1;
          let info = this.vote_block[up_key];
          this.vote_block[up_key] = '';
          this.vote_block[key] = '';
          this.$set(this.vote_block, up_key, block_msg)
          this.$set(this.vote_block, key, info)
        } else if (msg && 'down'==msg) {
          let up_key = key + 1;
          let info = this.vote_block[up_key];
          console.log('block_msg',block_msg);
          this.vote_block[up_key] = '';
          this.vote_block[key] = '';
          this.$set(this.vote_block, up_key, block_msg);
          this.$set(this.vote_block, key, info);

          console.log('vote_block_down',this.vote_block);
        }
      },
      change_click_msg(msg,voteOrder) {
        this.now_node = msg;
        this.voteOrder = voteOrder;
        console.log('voteOrder',voteOrder);
        if ('vote_order' != msg) {
          this.$refs.components_tip_box[voteOrder].change_cancel();
        } else if ('desc_title' != msg) {
          this.showe_title_desc = false;
          this.title_desc_class = '';
          this.dec_choose_line = false;
          this.dec_gray_line = false;
        }
      },
      set_vote_order:function(voteOrder){
        this.voteOrder = voteOrder;
        console.log('set_vote_order',voteOrder);
      },
      all_click(e) {
        let sp = '';
        console.log('e', e.target );
        if (this.now_node == 'desc_title') {
          sp = this.$refs.desc_title;
          let img = this.$refs.desc_title_img;
          if(sp || img){
            if((!sp || !sp.contains(e.target)) && (!img || !img.contains(e.target))){
              this.showe_title_desc = false;
              this.title_desc_class = '';
              this.dec_choose_line = false;
              this.dec_gray_line = false;
            }
          }
        } else if (this.now_node == 'vote_order') {
          for(let j=0; j<this.vote_block.length;j++) {
            this.$refs.components_tip_box[j].change_vote_order(e.target);
          }
        }
        console.log('全屏点击',sp)
      },
      change_style: function(info) {
        if ('left' == info) {
          this.vote_data.vote_des_style = 'text-align:left;';
          this.vote_des_style_class = 'style_left';
          this.left_class = 'active';
          this.center_class = '';
        } else {
          this.vote_data.vote_des_style = 'text-align:center;';
          this.vote_des_style_class = 'style_center';
          this.left_class = '';
          this.center_class = 'active';
        }
      },
      up_img: function() {
        console.log('触发上传图片')
        this.$refs.tempUploadFile.click();
      },
      focus_title(e) {
        console.log('focus_title')
        if(e.target && this.vote_title_placeholder){
          this.vote_title_placeholder = '';
        }
      },
      blur_title(e) {
        if(e.target && !this.vote_title_placeholder){
          this.vote_title_placeholder = '请输入表单标题';
        }
      },
      hover_info(e) {
        console.log('覆盖')
        this.dec_gray_line = true;
      },
      leave_info(e) {
        console.log('离开')
        if(e.target && this.dec_gray_line){
          this.dec_gray_line = false;
        }
      },
      handleClose (e) {
        if(e.target && this.showeditAlign){
          this.showeditAlign = true;
        }
      },
      focus_info (e) {
        console.log('焦点')
        if(e.target && !this.showe_title_desc){
          this.showe_title_desc = true;
          this.title_desc_class = 'choose_box';
          this.dec_choose_line = true;
          this.dec_gray_line = false;
          this.change_click_msg('desc_title',0);
        }
