<template>
  <div class="score_vote_box" :style="is_focus_width ? 'width: 680px;' : 'width: 640px;'" @click="score_vote_click">
      <div class="tip_box" :class="{'choose_box': voteOrder === choose_order}" ref="vote_order">
        <el-row>
          <el-col :span="1" class="tip_sort">
             {{voteOrder}}.
          </el-col>
          <el-col :span="23" class="tip_info">

            <div @mouseover="hover_info" @mouseleave="leave_info">
              <el-input
                class="ant-input" :class="{'gray_line': dec_gray_line, 'choose_line': dec_choose_line}"
                type="textarea"
                :autosize="{ minRows: 1, maxRows: 10}"
                placeholder="输入问题"
                @focus="tip_focus(voteOrder)"
                maxlength="1000"
                v-model="vote_block_msg.block_title">
              </el-input>
            </div>

<!--            <textarea maxlength="300" class="ant-input" v-model="vote_block_msg.block_title" placeholder="输入问题" @focus="tip_focus(voteOrder)" ></textarea>-->
          </el-col>
        </el-row>
<!--        <div class="gray_line" v-show="dec_gray_line"></div>-->
<!--        <div class="choose_line" v-show="dec_choose_line"></div>-->

        <el-row>
          <el-col :span="24">
            <div class="tip_content">
              <el-rate v-model="score" disabled="" :disabled-void-color="void_color"></el-rate>
            </div>
          </el-col>
        </el-row>

        <el-row class="tip_set" v-show="tip_set">
          <el-col :span="2">&nbsp;</el-col>
          <el-col :span="22" class="set_box">
            <el-switch
              inactive-text="必填"
              v-model="vote_block_msg.is_write"
              active-color="#1890ff"
              inactive-color="#DCDFE6"
              active-value="1"
              inactive-value="2">
            </el-switch>
            <el-tag @click="copy_tip">复制</el-tag>
            <el-tag v-if="voteOrder>1" @click="move_tip('up')">上移</el-tag>
            <el-tag v-if="voteOrder < block_length" @click="move_tip('down')">下移</el-tag>
            <el-tag type="info" @click="del_tip">删除</el-tag>
          </el-col>
        </el-row>
      </div>
  </div>
</template>

<script>
  export default {
    name: 'completion_vote',
    data () {
      return {
        dec_gray_line: false,
        is_focus_width: false,
        dec_choose_line: false,
        tip_set: false,
        tip_box_class: '',
        choose_order: '',
        score:0,
        void_color: '#aeb5c0',
        vote_block_msg: this.vote_block
      }
    },
    methods: {
      score_vote_click: function (e) {
        console.log('vote_block',this.vote_block_msg);
        this.choose_order = this.voteOrder;
        this.tip_set = true;
        this.is_focus_width = true;
      },
      tip_focus: function (voteOrder) {
        this.dec_choose_line = true;
        this.dec_gray_line = false;
        this.$parent.change_click_msg('vote_order', voteOrder-1);
      },
      copy_tip: function () {
        this.$parent.copy_tip(this.voteOrder,this.vote_block_msg,3);
      },
      move_tip: function (msg) {
        this.$parent.move_tip(this.voteOrder,msg);
      },
      change_vote_order: function (target_msg) {
        console.log('子组件被调用')
        console.log('voteOrder1',this.voteOrder);
        let sp = this.$refs.vote_order;
        if(sp){
          if(!sp.contains(target_msg) && this.voteOrder>0){
            this.change_cancel();
          } else {
            this.$parent.set_vote_order(this.voteOrder-1);
          }
        }
      },
      change_cancel: function () {
        console.log('子组件被调用')
        this.choose_order = 0;
        this.tip_set = false;
        this.dec_choose_line = false;
        this.dec_gray_line = false;
        this.is_focus_width = false;
      },
      hover_info(e) {
        console.log('覆盖')
        this.dec_gray_line = true;
      },
      leave_info(e) {
        console.log('离开')
        if(e.target && this.dec_gray_line){
          this.dec_gray_line = false;
        }
      },
      del_tip(e) {
        console.log('删除',this.block)
        if(e.target && this.voteOrder){
          this.$parent.deleteTip(this.voteOrder-1);
        }
      }
    },
    props: ["vote-order",'block_length','vote_block']
  }
</script>

